def seed_baselines(apps, schema_editor):
    """Existing receipts: assume SAP has not absorbed any of them yet (baseline = SAP delivered now)."""
    POReceipt = apps.get_model('so', 'POReceipt')
    POLineBaseline = apps.get_model('so', 'POLineBaseline')
    Item = apps.get_model('so', 'SAPPurchaseOrderItem')
    pairs = POReceipt.objects.values_list('po_number', 'line_no').distinct()
    for po_number, line_no in pairs:
        item = Item.objects.filter(purchaseorder__po_number=po_number, line_no=line_no).first()
        if not item:
            continue
        rem = item.remaining_open_quantity
        delivered = max(0, (item.quantity or 0) - rem) if rem is not None else 0
        POLineBaseline.objects.get_or_create(
            po_number=po_number, line_no=line_no, defaults={'sap_delivered_at_start': delivered},
        )


